// src/legacyMapText.ts
var oldLabelsById = new Map(legacyMapText1627_default.map((label) => [label.id, label]));
var MAP_ASSET_KEY = "map-data/ming_provinces.json";
var BASE_MAP_ASSET_KEY = "home-map-assets/base/ming-map.webp";
function validateLegacyMapText(root, scan) {
  const assetPaths = (scan ?? scanModFiles(root)).assetPaths;
  const mapFile = assetPaths.get(MAP_ASSET_KEY);
  if (!mapFile || assetPaths.has(BASE_MAP_ASSET_KEY)) return [];
  let parsed;
  try {
    parsed = JSON.parse(readFileSync11(mapFile, "utf8"));
  } catch {
    return [];
  }
  if (!validateMapFeatureCollection(parsed).valid || !isPlainRecord(parsed) || !Array.isArray(parsed.features)) return [];
  const mapRelativePath = path17.relative(root, mapFile).split(path17.sep).join("/");
  const issues = [];
  parsed.features.forEach((feature, index) => {
    if (!isPlainRecord(feature) || feature.type !== "Feature" || !isPlainRecord(feature.properties) || !isPlainRecord(feature.geometry)) return;
    const properties = feature.properties;
    const geometry = feature.geometry;
    if (properties.type !== "text" || typeof properties.id !== "string" || geometry.type !== "Point") return;
    const old = oldLabelsById.get(properties.id);
    const coordinates = geometry.coordinates;
    if (!old || feature.id !== old.id || properties.name !== old.name || !Array.isArray(coordinates) || coordinates.length !== 2 || coordinates[0] !== old.coordinates[0] || coordinates[1] !== old.coordinates[1]) return;
    issues.push({
      id: `legacy-map-text-overlap-${old.id}-${index + 1}`,
      level: "cross_table",
      severity: "warning",
      code: "asset-reference",
      reasonCode: "legacy-map-text-overlap",
      reasonData: { path: mapRelativePath, id: old.id, name: old.name },
      table: "map_province",
      rowKey: `feature-${index + 1}`,
      message: `${mapRelativePath} \u7B2C ${index + 1} \u4E2A\u8981\u7D20\u201C${old.name}\u201D\u662F\u65E7\u7248\u5185\u7F6E\u5730\u540D\uFF1B1.6.0 \u5B98\u65B9\u5E95\u56FE\u5DF2\u542B\u6B64\u6587\u5B57\uFF0C\u6CBF\u7528\u5B98\u65B9\u5E95\u56FE\u4F1A\u53E0\u5B57\u3002\u8BF7\u79FB\u9664\u8BE5 text \u8981\u7D20\uFF0C\u6216\u63D0\u4F9B\u6709\u6548\u7684 ${BASE_MAP_ASSET_KEY} \u81EA\u5B9A\u4E49\u5E95\u56FE\u8986\u76D6`
    });
  });
  return issues;
}

// src/validate.ts
function codeNameSet(rows) {
  return new Set((rows ?? []).map((row) => String(row.code_name ?? "")).filter((value) => value !== ""));
}
async function validateDirectory(directory, options = {}) {
  await assertDirectoryExists(directory);
  const root = path18.resolve(directory);
  const onProgress = options.onProgress;
  onProgress?.("\u9636\u6BB5 1/5\uFF1A\u52A0\u8F7D\u8868\u6570\u636E");
  const schema = new SchemaRegistry(MOD_MAKER_CSV_SCHEMA);
  const source = createFsModFileSource(root);
  const loaded = await loadTables(schema, source, { normalizeRows: defaultNormalizeRows });
  const assetScan = scanModFiles(root);
  onProgress?.("\u9636\u6BB5 2/5\uFF1A\u8DE8\u8868\u4E0E\u89C4\u5219\u6821\u9A8C");
  const issues = [...loaded.issues];
  issues.push(...validateAll(schema, loaded.data));
  issues.push(...validateAssetReferences(root));
  issues.push(...validateRegisteredJsonFiles(root));
  issues.push(...validateLegacyMapText(root, assetScan));
  issues.push(
    ...validateJsonCrossTable(root, {
      regimesCodes: codeNameSet(loaded.data.regimes),
      provincesCodes: codeNameSet(loaded.data.provinces)
    })
  );
  onProgress?.("\u9636\u6BB5 3/5\uFF1A\u8D44\u4EA7\u5F15\u7528\u5B8C\u6574\u6027");
  issues.push(...await validateAssetExistence(root, loaded.data, { scan: assetScan }));
  issues.push(...await validateTroopImageAssets(root, loaded.data, { scan: assetScan }));
  onProgress?.("\u9636\u6BB5 4/5\uFF1A\u6D3E\u751F\u4E00\u81F4\u6027");
  issues.push(...await validateDerivedConsistency(root, loaded.data));
  issues.push(...validateFieldDefinitionsOverride(root, { scan: assetScan }));
  onProgress?.("\u9636\u6BB5 5/5\uFF1Aprompt \u5C42\u5DE1\u68C0\u4E0E\u6C47\u603B");
  const promptLayer = inspectPromptLayer(root);
  issues.push(...promptLayer.issues);
  for (const [index, row] of (loaded.data.decisions ?? []).entries()) {
    for (const item of inspectDecisionRepeatPolicy(row.repeat_policy).warnings) {
      issues.push({
        id: `decision-policy-${index}-${item.field}`,
        code: "csv-schema",
        level: "field",
        severity: "warning",
        table: "decisions",
        rowKey: String(row.__rowId ?? ""),
        column: "repeat_policy",
        message: `${item.field}: ${item.message}`
      });
    }
  }
  const errorCount = issues.filter((issue4) => issue4.severity === "error").length;
  const warningCount = issues.filter((issue4) => issue4.severity === "warning").length;
  const presentTables = schema.listTables().map((table) => table.name).filter((name) => !loaded.missingTables.includes(name)).filter((name) => !loaded.misplacedTables.some((item) => item.table === name));
  return {
    directory: root,
    schemaVersion: schema.version,
    valid: errorCount === 0,
    errorCount,
    warningCount,
    issueCount: issues.length,
    issues,
    contractCoverage: {
      expectedTables: schema.listTables().length,
      presentTables,
      missing: loaded.missingTables,
      misplaced: loaded.misplacedTables,
      missingSettingPrompts: promptLayer.missingSettingPrompts,
      promptLayers: promptLayer.promptLayers,
      inertPromptNames: promptLayer.inertPromptNames
    },
    manifestMissing: !manifestFileExists(root),
    tablesFound: presentTables.length
  };
}
function applyIssueLimit(report, limit, offset = 0) {
  const limited = applyListLimit(report.issues, limit, offset);
  return {
    ...report,
    issues: limited.returned,
    truncated: limited.hasMore,
    returnedCount: limited.returned.length,
    offset: limited.offset,
    hasMore: limited.hasMore,
    nextOffset: limited.nextOffset
  };
}

