// src/tools/charBudget.ts
var TEXT_CHAR_LIMIT2 = CONTENT_PREFLIGHT_CONTRACT_V2.limits.maxTextCodePoints;
function countCodePoints(text) {
  return Array.from(text).length;
}
function charBudgetMeta(text) {
  return { charCount: countCodePoints(text), charLimit: TEXT_CHAR_LIMIT2 };
}

// src/tools/schemaTools.ts
function schemaTableNames() {
  return Object.keys(MOD_CSV_SCHEMA.tables);
}
function schemaJsonLogicalNames() {
  return Object.keys(JSON_SCHEMA_CATALOG);
}
function validTablesHint() {
  return `\u6709\u6548\u8868\uFF1A${schemaTableNames().join("\u3001")}`;
}
